# Generated by dev/kat/emit_golden.R -- do not edit by hand.
#
# Cross-platform golden values. CI runs this on macOS, Windows, Linux
# (release + oldrel), clang23, gcc16, 32-bit i386 and musl; stateless
# generation promises every one of them produces identical values, and this
# is the only thing that actually checks it.
#
# These are a snapshot of zurand's own output, which is circular on its own.
# It is not circular in combination: test-kat.R pins the underlying bit
# stream against Random123's published vectors and an independent from-spec
# implementation, so what remains unverified is only the transforms, and
# that is exactly what these values fix in place.
#
# A failure here means either a real portability bug or a deliberate change
# to the stream. Regenerate only for the latter, and say so in the commit.
#
# Values are hex float literals because decimal ones are not portable: R on
# arm64 mis-rounds at least one 17-digit literal these tests need. Hex is
# exact, so a failure is always about zurand and never about the parser.

test_that("rng_uniform() is bit-stable", {
  expect_identical(rng_uniform(rng_key(42L), 12L),
    c(
      0x1.94892844f95b3p-1, 0x1.755a733c937bdp-1, 0x1.02e656ef8b9c5p-1,
      0x1.de7fc5b9fac18p-4, 0x1.28d0ec0331c84p-3, 0x1.217a5097cf953p-1,
      0x1.13922cd11f8b1p-1, 0x1.8f680c18ba557p-1, 0x1.0c3ba5f7a84d5p-1,
      0x1.51284d42ea72bp-1, 0x1.c5c477c80e57fp-1, 0x1.300957b62323p-5
    ))

  expect_identical(rng_uniform(rng_key(42L), 4L, min = -2, max = 5),
    c(
      0x1.c3f00678b45fap+1, 0x1.8d5e49aa0218ap+1, 0x1.8a26304668a32p+0,
      -0x1.2ea8197ea24b6p+0
    ))
})

test_that("rng_normal() is bit-stable, including the ziggurat slow paths", {
  expect_identical(rng_normal(rng_key(42L), 12L),
    c(
      0x1.eaf3a6731a5acp-3, 0x1.5da3eb05253b7p-1, 0x1.05605afe8dea1p-2,
      0x1.938a55bc3ab33p+0, 0x1.87e22300ef1bdp-1, -0x1.284c25bf4ee9ep+1,
      -0x1.f3260b407018p-1, -0x1.0b26fc6d6d0a6p+0, 0x1.bc0a4941cf33ep-1,
      0x1.406caf8b6ad26p+1, 0x1.a5b95a7214226p-5, -0x1.3d0a2d184f845p-1
    ))

  # Indices whose |z| >= 3.6542: the fast path cannot produce these, so they
  # pin the wedge and tail branches that most of the C code exists to serve.
  tail_idx <- c(1178L, 2172L, 4062L, 11756L, 13112L, 15279L, 28487L, 31217L)
  expect_identical(rng_normal(rng_key(42L), 200000L)[tail_idx],
    c(
      -0x1.dab829352c64fp+1, 0x1.e33d338a8b521p+1, 0x1.e15104edb253cp+1,
      0x1.e9dbc8aa84804p+1, -0x1.fe1f18f1827a2p+1, 0x1.f4489461bf7bap+1,
      -0x1.00d548d92c897p+2, -0x1.d6785e4c6308ap+1
    ))

  expect_identical(rng_normal(rng_key(42L), 4L, mean = 2, sd = 3),
    c(
      0x1.5c0daf3594f1p+1, 0x1.031d7821edf64p+2, 0x1.6204221f7537cp+1,
      0x1.aea7c04d2c066p+2
    ))
})

test_that("rng_integer() is bit-stable, including the rejection path", {
  expect_identical(rng_integer(rng_key(42L), 12L, min = 1L, max = 6L),
    c(
      2L, 2L, 1L, 5L, 5L, 2L, 3L, 3L, 2L, 2L, 4L, 1L
    ))

  # A near-maximal range makes Lemire rejection actually fire.
  expect_identical(rng_integer(rng_key(42L), 8L, min = 1L, max = 2000000000L),
    c(
      352578979L, 449361876L, 108978621L, 1398085695L, 1538485321L,
      638067389L, 977655369L, 980169362L
    ))

  # A range wider than 2^31: the offset above min no longer fits an int, so
  # this is the case that must not be computed as min + (int)offset.
  expect_identical(rng_integer(rng_key(42L), 8L, min = -2000000000L, max = 2000000000L),
    c(
      -1294842043L, -1101276249L, -1782042759L, 796171389L, 1076970642L,
      -723865223L, -44689263L, -39661276L
    ))
})

test_that("rng_fold() derives stable keys", {
  expect_identical(format(rng_fold(rng_key(42L), "layer1")),
    c(
      "rng_key[8dbacb9f407ebc3ae10ed1561177db53]"
    ))
  expect_identical(format(rng_fold(rng_key(42L), 7L)),
    c(
      "rng_key[a11aab0f92e75bb8303c089c13db8156]"
    ))
})

test_that("multi-key matrices are bit-stable", {
  # Column j must equal the single-key draw for key j; this pins the layout
  # as well as the values.
  expect_identical(as.vector(rng_normal(rng_key(42L, n = 3L), 4L)),
    c(
      0x1.eaf3a6731a5acp-3, 0x1.5da3eb05253b7p-1, 0x1.05605afe8dea1p-2,
      0x1.938a55bc3ab33p+0, -0x1.d3c185913a391p-1, -0x1.2e13522a66651p-3,
      0x1.62c9710da6bbap-2, 0x1.8280495aa9f7dp+0, -0x1.c34e037c85693p+0,
      -0x1.b5118f8401022p-3, -0x1.042b1290bfe1fp-1, 0x1.caf73ec4271a2p-2
    ))
})

test_that("the threefry4x64 engine is bit-stable", {
  # A second engine must be as reproducible as the first, and must produce a
  # different stream from the same seed -- a key records its engine.
  expect_identical(rng_uniform(rng_key(42L, engine = "threefry4x64"), 8L),
    c(
      0x1.5897a6b8bdd9cp-3, 0x1.4673851d43bccp-3, 0x1.d970ecb43db98p-4,
      0x1.7d92d9532840fp-1, 0x1.a645b682d7436p-2, 0x1.818fbe5879e7p-5,
      0x1.32c62654eca26p-2, 0x1.daf5d18731dc4p-3
    ))

  expect_identical(rng_normal(rng_key(42L, engine = "threefry4x64"), 8L),
    c(
      0x1.73fa9e85e3404p-2, -0x1.e2f195a626ee6p+0, -0x1.471f0b60d07e2p+1,
      0x1.9086f0d2cc325p-3, -0x1.7b3f06b84fd85p+0, -0x1.71054b72ccbdbp-1,
      -0x1.3eb001b919aa3p-3, -0x1.fa9e05411b387p-1
    ))

  expect_identical(rng_integer(rng_key(42L, engine = "threefry4x64"), 8L, min = 1L, max = 6L),
    c(
      3L, 4L, 6L, 3L, 3L, 6L, 3L, 6L
    ))

  expect_false(identical(rng_normal(rng_key(42L), 64L),
                         rng_normal(rng_key(42L, engine = "threefry4x64"), 64L)))
  expect_identical(attr(rng_key(1L, engine = "threefry4x64"), "engine"),
                   "threefry4x64")
})

test_that("the xoshiro256pp engine is bit-stable", {
  # Values either side of a 512-word chunk boundary, since that is where
  # this engine reseeds and the only place its indexing could go wrong.
  expect_identical(rng_uniform(rng_key(42L, engine = "xoshiro256pp"), 8L),
    c(
      0x1.2a581f80c437p-5, 0x1.ab2018f5da24dp-1, 0x1.e4334cceac67ap-2,
      0x1.6a7784e81a88p-8, 0x1.be3ba9c4dcadbp-1, 0x1.a3ed6b35e7622p-2,
      0x1.910a74a0ac7b6p-2, 0x1.7d5150edfa817p-1
    ))

  expect_identical(rng_normal(rng_key(42L, engine = "xoshiro256pp"), 8L),
    c(
      -0x1.36e7186c4f557p+0, 0x1.9b7c19da02f9fp+0, -0x1.3e745a307bf21p-1,
      0x1.905276bc6b61ap-1, 0x1.6c338450b9db6p-1, 0x1.56dac9dfb8d1p+0,
      -0x1.b9b8c577125f8p-1, 0x1.9a051051413f4p-2
    ))

  expect_identical(rng_uniform(rng_key(42L, engine = "xoshiro256pp"), 1030L)[508:520],
    c(
      0x1.173d0de51886fp-1, 0x1.7923105527bbdp-1, 0x1.44b43d9e80b66p-2,
      0x1.b078f6407c3afp-1, 0x1.f399030c36676p-2, 0x1.d6f79ebed95edp-1,
      0x1.8d2909b26a29bp-1, 0x1.1c6e147599dbcp-3, 0x1.c6e3e615d6fd7p-1,
      0x1.4e51bf05f26ep-6, 0x1.46f3b6de802cfp-1, 0x1.e3020d45b0c6ep-2,
      0x1.e05aec585b2e7p-1
    ))

  expect_identical(rng_integer(rng_key(42L, engine = "xoshiro256pp"), 8L, min = 1L, max = 6L),
    c(
      1L, 5L, 3L, 5L, 2L, 1L, 4L, 5L
    ))

  expect_identical(as.character(rng_bits(rng_key(42L, engine = "xoshiro256pp"), 6L, bits = 64L)),
    c(
      "1b56f8cdd2f1eb5e", "6f452a520ec8e62f", "244edfface7c6cd1",
      "0a1d672e40c991eb", "2f7e7b02530edffc", "87251fef7a1b81a0"
    ))

  expect_false(identical(rng_normal(rng_key(42L), 64L),
                         rng_normal(rng_key(42L, engine = "xoshiro256pp"), 64L)))

  # A xoshiro key is a Philox key, so it folds with Philox: the derived key
  # words must equal what the same seed folds to under the philox engine,
  # with only the engine attribute differing. A two-way dispatch once sent
  # these down the threefry path; this pins the fix.
  fx <- rng_fold(rng_key(42L, engine = "xoshiro256pp"), "layer1")
  expect_identical(unclass(fx)[1L, ], unclass(rng_fold(rng_key(42L), "layer1"))[1L, ])
  expect_identical(attr(fx, "engine"), "xoshiro256pp")
  expect_identical(format(rng_fold(rng_key(42L, engine = "xoshiro256pp"), "layer1")),
    c(
      "rng_key[8dbacb9f407ebc3ae10ed1561177db53]"
    ))
})

test_that("draw i does not depend on n", {
  # The core counter-mode invariant, stated directly rather than implied.
  for (eng in c("philox4x64", "threefry4x64", "xoshiro256pp")) {
    key <- rng_key(99L, engine = eng)
    # 511/512/513 straddle the xoshiro chunk boundary.
    for (nn in c(3L, 17L, 64L, 257L, 511L, 512L, 513L, 1000L)) {
      expect_identical(rng_uniform(key, nn), rng_uniform(key, 1000L)[seq_len(nn)])
      expect_identical(rng_normal(key, nn), rng_normal(key, 1000L)[seq_len(nn)])
    }
  }
})
